<?php
 #[\AllowDynamicProperties] class TableBand { public $index; public $parent; public $children; } #[\AllowDynamicProperties] class TableBands { public $ofIndex; public $ofName; public $root; } #[\AllowDynamicProperties] class Table { public $id; public $nm; public $cols; public $rows; public $cells; public $styles; public $filled; public $calculatedCells; public $hiddenCells; public static $allTables = []; public static function get ($id) { if (Engine::$isBatch) { self::$allTables = []; } if (!isset(self::$allTables[$id])) { $db = Engine::$db; $sql = <<<'EOT'
select
    Json "json",
    Hash "hash"
from
    GenTableVersion
where
    GenTableVersionCode = ?
EOT;
$stmt = $db->prepare($sql); $stmt->execute([$id]); $row = $stmt->fetch(); $table = new Table; $table->id = $id; $table->hash = $row['hash']; $table->compile($row['json']); } return self::$allTables[$id]; } public static function isParentBand ($band, $gravityBand) { while (isset($gravityBand->parent)) { if (($gravityBand = $gravityBand->parent) === $band) { return true; } } return false; } public static function isChildrenBand ($band, $gravityBand) { foreach ($gravityBand->children as $child) { if ($child === $band) { return true; } if (isset($child->children)) { if (self::isChildrenBand($band, $child)) { return true; } } } return false; } private function compile ($json) { $params = Engine::$params; self::$allTables[$this->id] = $this; $data = safe_json_decode($json); checkJsonDecode(); mergeObjects($this, $data); $this->filled = 0; $this->cols = new TableBands; $colIndex = 0; $this->compileBands($this->cols, $data->cols, $colIndex); $this->cols->root = $data->cols; $this->rows = new TableBands; $rowIndex = 0; $this->compileBands($this->rows, $data->rows, $rowIndex); $this->rows->root = $data->rows; $this->compileCells(); } private function compileBands ($bands, $parent, &$index) { foreach ($parent->children as $band) { $band->parent = $parent; $band->index = $index; $bands->ofIndex[$index++] = $band; $bands->ofName[$band->nm] = $band; $this->filled |= isset($band) ? 1 : 0; if (isset($band->children)) { $this->compileBands($bands, $band, $index); } } } private function compileCells () { $colOfIndex = $this->cols->ofIndex; $colOfName = $this->cols->ofName; $rowOfIndex = $this->rows->ofIndex; $rowOfName = $this->rows->ofName; $styles = $this->styles; $calculatedCells = []; $hiddenCells = []; foreach ($this->cells as $id => $cell) { $pos = safe_explode(':', $id, 2); $col = $colOfName[$pos[0]]; $row = $rowOfName[$pos[1]]; $style = $styles->{$cell->st}; if ($style->fl & 0x10 || isset($cell->fc)) { if (isset($cell->fa)) { if ($cell->fa[0] === 'col') { if (isset($col->fa)) { $cell->ft = 2; } else if (isset($row->fa)) { $cell->ft = 3; } } else { $cell->ft = 1; } } else if (isset($row->fa)) { $cell->ft = 3; } else if (isset($col->fa)) { $cell->ft = 2; } if (isset($cell->ft) || isset($cell->fc)) { $calculatedCells[] = $id; } } $uc = isset($cell->uc) ? $cell->uc : 0; $ur = isset($cell->ur) ? $cell->ur : 0; if ($uc || $ur) { $colIndex = $col->index; $rowIndex = $row->index; for ($c = $uc; $c >= 0; --$c) { for ($r = $ur; $r >= 0; --$r) { if ($r || $c) { $hiddenCells[$colOfIndex[$colIndex + $c]->nm.':'. $rowOfIndex[$rowIndex + $r]->nm ] = 1; } } } } } $this->calculatedCells = $calculatedCells; $this->hiddenCells = $hiddenCells; } public static function cleanupTables ($tables) { foreach ($tables as $table) { $table->cleanup(); } return $tables; } public function cleanup () { $this->cols = $this->cleanupBands($this->cols); $this->rows = $this->cleanupBands($this->rows); return $this; } private function cleanupBands ($bands) { foreach ($bands->ofIndex as $band) { unset($band->index); unset($band->parent); } return $bands->root; } } 